# Synthetic integration only: generated by real Java services and isolated SQLite.
source("lab/attested_prospective_evaluation.R")
path <- "../backend/target/prospective-attested-fixture.json"
key <- "../backend/target/prospective-fixture-public.pem"
source_id <- "SYNTHETIC-INTEGRATION-INSTALLATION"
x <- evaluate_attested_prospective(path,key,source_id,TRUE)
stopifnot(x$forecast_count==28,x$scored_count==24,x$excluded_count==4,
  x$attempt_count==28,x$unforecasted_attempt_count==1,
  x$source_authentication=="VERIFIED_SIGNATURE_SYNTHETIC_INTEGRATION_ONLY",
  x$personal_validation=="NOT_ESTABLISHED",x$personal_profile=="NOT_CREATED",
  all(unlist(x$six_scientific_targets)=="NOT_ESTABLISHED"),!x$can_apply,!x$can_schedule,
  x$scientific_scorecard$temporal_reference$same_event_count==24,
  x$scientific_scorecard$temporal_reference$identical_prediction_count==21,
  is.finite(x$scientific_scorecard$paired_comparison$mean_brier_difference))
# Closed-form references for the actual 20-success/4-error Java prefix.
observed <- c(rep(1,20),rep(0,4))
expected_p <- vapply(seq_along(observed),function(i)
  (sum(head(observed,i-1L))+1)/(i+1),numeric(1))
expected_recent <- vapply(seq_along(observed),function(i)
  (sum(tail(head(observed,i-1L),20L))+1)/(min(i-1L,20L)+2),numeric(1))
stopifnot(abs(x$metrics$brier-mean((expected_p-observed)^2))<1e-12,
  abs(x$scientific_scorecard$temporal_reference$brier-mean((expected_recent-observed)^2))<1e-12,
  abs(x$scientific_scorecard$paired_comparison$mean_brier_difference-
    mean((expected_p-observed)^2-(expected_recent-observed)^2))<1e-12)
stopifnot(identical(x,evaluate_attested_prospective(path,key,source_id,TRUE)))
expect_error <- function(expr) {
  failed <- FALSE
  tryCatch(force(expr),error=function(e)failed<<-TRUE)
  stopifnot(failed)
}
expect_error(evaluate_attested_prospective(path,key,source_id,FALSE))
expect_error(evaluate_attested_prospective(path,key,"other-installation",TRUE))
envelope <- jsonlite::fromJSON(path,simplifyVector=FALSE)
input <- jsonlite::fromJSON(envelope$inputJson,simplifyVector=FALSE)
emit <- function(input,env=envelope) {
  env$inputJson <- as.character(jsonlite::toJSON(input,auto_unbox=TRUE,null="null",digits=16))
  env$inputSha256 <- digest::digest(enc2utf8(env$inputJson),algo="sha256",serialize=FALSE)
  output <- tempfile(fileext=".json")
  writeLines(jsonlite::toJSON(env,auto_unbox=TRUE,null="null",digits=16),output)
  output
}
changed <- input;changed$sourceKind <- "OPERATIONAL_EVENT_STORE_V1"
expect_error(evaluate_attested_prospective(emit(changed),key,source_id,FALSE))
changed <- input;changed$events <- c(changed$events,changed$events[1L])
expect_error(evaluate_attested_prospective(emit(changed),key,source_id,TRUE))
expect_error(evaluate_prospective(emit(changed)))
forecasts <- which(vapply(input$events,function(e)e$event_type=="PREDICTION_COMMITTED",logical(1)))
answers <- which(vapply(input$events,function(e)e$event_type=="ANSWER_SUBMITTED",logical(1)))
patch <- function(index,fields) {
  out <- input
  node <- jsonlite::fromJSON(out$events[[index]]$payload_json,simplifyVector=FALSE)
  for (name in names(fields)) node[[name]] <- fields[[name]]
  out$events[[index]]$payload_json <- as.character(jsonlite::toJSON(node,auto_unbox=TRUE,null="null",digits=16))
  out
}
changed <- input;changed$events[[answers[1L]]]$occurred_at <- changed$events[[forecasts[1L]]]$recorded_at
expect_error(evaluate_prospective(emit(changed)))
changed <- input;changed$events[[answers[1L]]]$snapshot_rowid <- changed$events[[forecasts[1L]]]$snapshot_rowid
expect_error(evaluate_prospective(emit(changed)))
expect_error(evaluate_prospective(emit(patch(forecasts[1L],list(studentId="another-student")))))
expect_error(evaluate_prospective(emit(patch(forecasts[1L],list(probability=0.99)))))
expect_error(evaluate_prospective(emit(patch(forecasts[1L],list(evidenceEventIds=list(input$events[[answers[24L]]]$event_id))))))
expect_error(evaluate_prospective(emit(patch(answers[1L],list(usedHelp="false")))))
expect_error(evaluate_prospective(emit(patch(answers[1L],list(answerExposed=TRUE)))))
# Terminal help/exposure is excluded; no later forecast is refitted to hide the edit.
for (fields in list(list(answerExposed=TRUE),list(usedHelp=FALSE,helpType="MATERIAL_APOIO"),
                    list(helpDeclarationProvided=FALSE))) {
  terminal <- patch(answers[24L],fields)
  terminal$events <- terminal$events[seq_len(answers[24L])]
  stopifnot(evaluate_prospective(emit(terminal))$scored_count==23)
}
bad <- envelope;bad$signatureBase64 <- paste0("AAAA",substring(bad$signatureBase64,5))
expect_error(evaluate_attested_prospective(emit(input,bad),key,source_id,TRUE))
bad <- envelope;bad$signatureBase64 <- NULL;bad$trusted_source_authorized <- TRUE
expect_error(evaluate_attested_prospective(emit(input,bad),key,source_id,TRUE))
legacy <- patch(forecasts[1L],list(captureVersion=NULL,policyVersion=NULL))
legacy$events <- legacy$events[seq_len(answers[1L])]
legacy_report <- evaluate_prospective(emit(legacy),require_current_capture=TRUE)
stopifnot(legacy_report$scored_count==0,legacy_report$excluded_count==1,
  unlist(legacy_report$exclusions)=="LEGACY_CAPTURE_UNAUDITED_NOT_PERSONAL_EVIDENCE")
expect_error(evaluate_prospective(emit(patch(answers[1L],list(studentId="wrong-student")))))
# Retain genuinely old/unidentified history in denominators without inventing UUIDs.
legacy_answer <- input$events[[tail(answers,1L)]]
legacy_answer$event_id <- "historical-unidentified-answer"
legacy_answer$snapshot_rowid <- input$snapshotRowid+1
legacy_answer$payload_json <- '{"origin":"REAL_STUDY","isCorrect":true,"gabaritoStatus":"DEFINITIVO"}'
historical <- input;historical$snapshotRowid <- legacy_answer$snapshot_rowid
historical$events <- c(historical$events,list(legacy_answer))
historical_envelope <- envelope;historical_envelope$snapshotRowid <- historical$snapshotRowid
historical_report <- evaluate_prospective(emit(historical,historical_envelope),TRUE)
stopifnot(historical_report$scored_count==24,historical_report$unforecasted_attempt_count==2,
  historical_report$unidentified_legacy_attempt_count==1)
wrong_key <- tempfile();writeLines("UNTRUSTED KEY",wrong_key)
expect_error(evaluate_attested_prospective(path,wrong_key,source_id,TRUE))
cat("Authenticated Java -> export -> R: synthetic custody, strict chronology, identity, help, exposure, tamper and baseline/replay checks passed. No personal experiment.\n")

# Activation review: direct R entry cannot bypass size/type or live file-substitution guards.
expect_error(evaluate_attested_prospective(path,key,source_id,NA))
expect_error(evaluate_attested_prospective(path,key,source_id,"true"))
large_key <- tempfile();writeBin(as.raw(rep(0L,65537L)),large_key)
expect_error(evaluate_attested_prospective(path,large_key,source_id,TRUE))
original_evaluator <- evaluate_prospective
for (replace_key in c(FALSE,TRUE)) {
  copied_input <- tempfile();file.copy(path,copied_input)
  copied_key <- tempfile();file.copy(key,copied_key)
  evaluate_prospective <- function(...) {
    result <- original_evaluator(...)
    writeBin(charToRaw("substituted"),if(replace_key) copied_key else copied_input)
    result
  }
  tryCatch(expect_error(evaluate_attested_prospective(copied_input,copied_key,source_id,TRUE)),
           finally={evaluate_prospective <- original_evaluator})
}
cat("Activation boundary: bounded key input, explicit fixture Boolean and original file/key substitution rejected.\n")

original_system2 <- system2
system2 <- function(...) 127L
tryCatch(expect_error(evaluate_attested_prospective(path,key,source_id,TRUE)),
         finally={system2 <- original_system2})
expect_error(evaluate_attested_prospective(path,paste0(key,".absent"),source_id,TRUE))
cat("Missing verifier or external key fails closed; no authenticated result.\n")

expect_error(evaluate_attested_prospective(path,"../backend/target/prospective-other-fixture-public.pem",source_id,TRUE))
message <- tryCatch(evaluate_attested_prospective(path,large_key,source_id,TRUE),error=function(e)conditionMessage(e))
stopifnot(is.character(message),grepl("processing limit",message))
cat("Valid other RSA public key rejected; key-size error identifies the limit guard.\n")
